 [DllImport("user32.dll",CharSet=CharSet.Unicode)]static extern int GetWindowText(IntPtr window,System.Text.StringBuilder title,int count);
 static void Emit(INPUT i){if(SendInput(1,new[]{i},Marshal.SizeOf<INPUT>())!=1)throw new InvalidOperationException("SendInput failed");}
 static void KeyEvent(ushort vk,bool down){Emit(new INPUT{type=1,data=new UNION{key=new KEY{vk=vk,flags=down?0u:2u}}});}
 static void Mouse(uint flags,uint data){Emit(new INPUT{type=0,data=new UNION{mouse=new MOUSE{flags=flags,data=data}}});}
 static void Move(int x,int y){int l=GetSystemMetrics(76),t=GetSystemMetrics(77),w=GetSystemMetrics(78),h=GetSystemMetrics(79);if(w<=1||h<=1||x<l||x>=l+w||y<t||y>=t+h)throw new InvalidOperationException("Display bounds failed");Emit(new INPUT{type=0,data=new UNION{mouse=new MOUSE{x=(int)Math.Round((x-l)*65535d/(w-1)),y=(int)Math.Round((y-t)*65535d/(h-1)),flags=0xC001}}});}


 public static string Run(string app,string mode){return Run(false,app,mode);}
 public static string Run(bool source,string app,string mode){
  if(!System.Text.RegularExpressions.Regex.IsMatch(app,@"\\DBMV-Isolated-preflight-preflightpage-[0-9a-f]{32}\\app$"))throw new InvalidOperationException("Owned cold Preflight path required");
  if(Array.IndexOf(new[]{"pointer","key","back","choose","language","focus-title","focus-permission","passive","mount","reduced"},mode)<0)throw new InvalidOperationException("Fixed parent mode required");
  var oldDpi=SetThreadDpiAwarenessContext(new IntPtr(-4));bool down=false,key=false;POINT old;GetPhysicalCursorPos(out old);AutomationElement window=null;
  string transport=System.IO.Path.Combine(app,(source?"preflightpage-source-":"preflightpage-native-")+mode+"-transport.txt");string phase="inventory";
  System.IO.File.WriteAllText(transport,"begin="+DateTime.UtcNow.ToString("o")+" source="+source+" mode="+mode+"\n");
  try{
   Condition roots=Condition.TrueCondition;if(!source){var identity=System.IO.File.ReadAllText(System.IO.Path.Combine(app,"preflightpage-launch.json"));var pid=System.Text.RegularExpressions.Regex.Match(identity,"\\\"pid\\\"\\s*:\\s*(\\d+)");if(!pid.Success)throw new InvalidOperationException("Fresh owned launch PID absent");roots=new AndCondition(new PropertyCondition(AutomationElement.NameProperty,"Replica PreflightPage verification"),new PropertyCondition(AutomationElement.ProcessIdProperty,int.Parse(pid.Groups[1].Value)));}
   foreach(AutomationElement w in AutomationElement.RootElement.FindAll(TreeScope.Children,roots)){if(source&&!w.Current.Name.StartsWith("PreflightPage Input · original isolation",StringComparison.Ordinal))continue;var proc=System.Diagnostics.Process.GetProcessById(w.Current.ProcessId);bool match=source?proc.MainModule.FileName.EndsWith(@"\Microsoft\Edge\Application\msedge.exe",StringComparison.OrdinalIgnoreCase):proc.MainModule.FileName.Equals(System.IO.Path.Combine(app,"ReplicaProbe.exe"),StringComparison.OrdinalIgnoreCase);if(!match)continue;if(window!=null)throw new InvalidOperationException("Unique owned Preflight window required");window=w;}if(window==null)throw new InvalidOperationException("Owned parent absent");
   Func<Func<AutomationElement,bool>,AutomationElement> find=predicate=>{var stack=new System.Collections.Generic.Stack<Tuple<AutomationElement,int>>();stack.Push(Tuple.Create(window,0));int visits=0;var seen=new System.Collections.Generic.HashSet<string>();while(stack.Count>0&&visits++<400){var entry=stack.Pop();var e=entry.Item1;var rid=string.Join(",",e.GetRuntimeId());if(!seen.Add(rid))continue;if(predicate(e))return e;if(entry.Item2>=20)continue;var child=TreeWalker.ControlViewWalker.GetFirstChild(e);int children=0;while(child!=null&&children++<80){stack.Push(Tuple.Create(child,entry.Item2+1));child=TreeWalker.ControlViewWalker.GetNextSibling(child);}}return null;};
   phase="foreground";var frame=window.Current.BoundingRectangle;SetForegroundWindow(new IntPtr(window.Current.NativeWindowHandle));System.Threading.Thread.Sleep(120);Action guard=()=>{if(GetForegroundWindow().ToInt64()!=window.Current.NativeWindowHandle)throw new InvalidOperationException("Owned foreground lost");};guard();AutomationElement target=null;phase="target";
   Func<AutomationElement,bool> permission=e=>source?e.Current.ControlType==ControlType.Button&&(e.Current.Name=="필요한 권한 보기"||e.Current.Name=="Required permissions")&&e.Current.BoundingRectangle.Height>=88:e.Current.AutomationId=="CapabilityRow-permissions";
   if(mode=="key"){target=find(permission);if(target==null)throw new InvalidOperationException("Permission absent");target.SetFocus();System.Threading.Thread.Sleep(120);var focused=AutomationElement.FocusedElement;if(focused==null||!permission(focused))throw new InvalidOperationException("Fresh key predecessor absent");KeyEvent(13,true);key=true;System.Threading.Thread.Sleep(25);guard();KeyEvent(13,false);key=false;}
   else if(!source&&Array.IndexOf(new[]{"language","focus-title","focus-permission","mount","reduced"},mode)>=0){
    phase="diagnostic-utility";target=find(e=>e.Current.AutomationId=="PreflightPage-"+mode);if(target==null||target.Current.Name!=mode||!target.Current.IsEnabled||target.Current.IsOffscreen)throw new InvalidOperationException("Exact native diagnostic utility absent");
    System.IO.File.AppendAllText(transport,"guard=owned-PID/path/title+InvokePattern targetId="+target.Current.AutomationId+" targetName="+target.Current.Name+" scope=diagnostic-only\n");((InvokePattern)target.GetCurrentPattern(InvokePattern.Pattern)).Invoke();
   }
   else{
    string id=mode=="pointer"?"CapabilityRow-permissions":mode=="back"||mode=="choose"?"Footer-"+mode:"PreflightPage-"+mode;
    if(mode=="passive"){target=find(e=>e.Current.ControlType==ControlType.Text&&(e.Current.Name.StartsWith("기본 비교는 읽기 전용입니다.",StringComparison.Ordinal)||e.Current.Name.StartsWith("The default comparison is read-only.",StringComparison.Ordinal)));}else if(source&&mode=="pointer")target=find(permission);else target=find(e=>source?e.Current.ControlType==ControlType.Button&&e.Current.BoundingRectangle.Height>=88&&(mode=="back"?(e.Current.Name=="뒤로"||e.Current.Name=="Back"):mode=="choose"?(e.Current.Name=="검사 범위 선택"||e.Current.Name=="Choose checks"):e.Current.Name==mode):e.Current.AutomationId==id);
    if(target==null)throw new InvalidOperationException("Exact parent target absent "+id);phase="target-bounds";var b=target.Current.BoundingRectangle;var targetName=target.Current.Name;if(b.Width<=0||b.Height<=0||!target.Current.IsEnabled||target.Current.IsOffscreen||string.IsNullOrEmpty(targetName))throw new InvalidOperationException("Target geometry/name/enabled/visible guard failed");int x=(int)Math.Round(mode=="passive"?b.Left+20:b.Left+b.Width/2),y=(int)Math.Round(b.Top+b.Height/2);if(!frame.Contains(new System.Windows.Point(x,y)))throw new InvalidOperationException("Parent point outside window");phase="pointer-hit";Move(x,y);System.Threading.Thread.Sleep(60);guard();POINT actual;if(!GetPhysicalCursorPos(out actual)||Math.Abs(actual.x-x)>1||Math.Abs(actual.y-y)>1)throw new InvalidOperationException("Physical cursor mismatch");var hit=WindowFromPoint(actual);var root=GetAncestor(hit,2);uint hitPid;GetWindowThreadProcessId(root,out hitPid);var title=new System.Text.StringBuilder(512);GetWindowText(root,title,title.Capacity);var path=System.Diagnostics.Process.GetProcessById((int)hitPid).MainModule.FileName;var fresh=target.Current.BoundingRectangle;if(root.ToInt64()!=window.Current.NativeWindowHandle||hitPid!=window.Current.ProcessId||!fresh.Contains(new System.Windows.Point(actual.x,actual.y))||target.Current.Name!=targetName||!target.Current.IsEnabled||target.Current.IsOffscreen||(source?!title.ToString().StartsWith("PreflightPage Input · original isolation",StringComparison.Ordinal)||!path.EndsWith(@"\Microsoft\Edge\Application\msedge.exe",StringComparison.OrdinalIgnoreCase):title.ToString()!="Replica PreflightPage verification"||!path.Equals(System.IO.Path.Combine(app,"ReplicaProbe.exe"),StringComparison.OrdinalIgnoreCase)))throw new InvalidOperationException("Fresh owned Win32 hit/target guard failed");System.IO.File.AppendAllText(transport,"guard=WindowFromPoint+GA_ROOT dpi="+GetAwarenessFromDpiAwarenessContext(GetThreadDpiAwarenessContext())+" requested="+x+","+y+" actual="+actual.x+","+actual.y+" hitHwnd="+hit+" rootHwnd="+root+" pid="+hitPid+" path="+path+" title="+title+" targetId="+target.Current.AutomationId+" targetName="+targetName+" enabled=true visible=true\n");phase="pointer-down";Mouse(2,0);down=true;System.Threading.Thread.Sleep(25);guard();Mouse(4,0);down=false;
   }
   System.Threading.Thread.Sleep(650);guard();var f=AutomationElement.FocusedElement;System.IO.File.AppendAllText(transport,"postFocus="+(f==null?"none":f.Current.AutomationId)+"\n");if(source)return "Fresh source parent physical scope completed";using(var stream=new System.IO.FileStream(System.IO.Path.Combine(app,"preflightpage-input.json"),System.IO.FileMode.Open,System.IO.FileAccess.Read,System.IO.FileShare.ReadWrite|System.IO.FileShare.Delete))using(var reader=new System.IO.StreamReader(stream))return reader.ReadToEnd();
  }catch(Exception error){System.IO.File.AppendAllText(transport,"failure-phase="+phase+" error="+error.GetType().Name+" "+error.Message+"\n");throw;}finally{if(key)KeyEvent(13,false);if(down)Mouse(4,0);if(window!=null&&GetForegroundWindow().ToInt64()==window.Current.NativeWindowHandle)Move(old.x,old.y);if(oldDpi!=IntPtr.Zero)SetThreadDpiAwarenessContext(oldDpi);}
 }
